-file("src/data/talisman_data.erl", 1).

-module(talisman_data).

-export([get/1,
         get_set/1,
         get_fusion/1,
         get_special/1,
         get_step_list/1,
         get_step_ratio/1,
         get_num/1,
         get_base_fc/1,
         get_special_fc/1,
         get_fusion_fc/1,
         get_bag_fusion/1,
         get_absorb/1,
         get_absorb_star_trans/1,
         get_enable_absorb_num/1,
         get_absorb_set_id_map/1,
         get_rival_set/1,
         get_classes_modify/1,
         get_talisman_convert/1,
         get_formula_list/0,
         get_formula/1,
         get_formula_group_list/0,
         get_formula_group/1,
         get_covert_cost/1,
         get_add_volume/1]).

-file("inc/common.hrl", 1).

-type p() :: bitstring().

-type z() :: non_neg_integer().

-type role_id() :: {pos_integer(), p(), z()}.

-type unit_id() :: {pos_integer(), pos_integer()}.

-type pos() :: {pos_integer(),
                non_neg_integer(),
                non_neg_integer()}.

-record(center,
        {ready = 0 :: 1 | 0,
         pid :: undefined | pid(),
         node :: undefined | atom(),
         center_platform = "" :: list(),
         center_zone_id = 0 :: non_neg_integer(),
         platform = <<>> :: bitstring(),
         zone_id = 0 :: non_neg_integer(),
         combine = [] :: [{bitstring(), non_neg_integer()}]}).

-record(notice_rec,
        {type = 11, digit_attr = [], str_attr = []}).

-file("src/data/talisman_data.erl", 40).

-file("inc/talisman.hrl", 1).

-record(m_talisman,
        {ver = 5,
         next_id = 1,
         use_plan = 1,
         plan_1 = [],
         plan_2 = [],
         items = [],
         fusion_lev = 0,
         fusion_val = 0,
         skills = [],
         fc = 0,
         remold_formula = [],
         last_gain_id = 0,
         volume = 48}).

-record(talisman,
        {ver = 3,
         id = 1,
         base_id = 0,
         type = 0,
         quality = 0,
         lev = 0,
         attr = [],
         num = 1,
         fc = 0}).

-record(talisman_base,
        {base_id = 0,
         name = "",
         type = 0,
         quality = 0,
         lev = 0,
         need_lev = 0,
         need_lev_break = 0,
         set_id = 0,
         fusion_val = 0,
         base_attr = [],
         grade = 0}).

